const { useState } = React;

const Slider = ({ label, value, min, max, step, onChange, format }) => (
  <label className="flex min-w-[200px] flex-1 items-center gap-3">
    <span className="shrink-0 text-tau-sm text-ink-2">{label}</span>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
    />
    <span className="w-12 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{format(value)}</span>
  </label>
);

const Chip = ({ children }) => (
  <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{children}</code>
);

const Component = () => {
  const [fontSize, setFontSize] = useState(15);
  const [lineHeight, setLineHeight] = useState(1.8);
  const [lines, setLines] = useState(3);
  const [expanded, setExpanded] = useState(false);
  const [ruled, setRuled] = useState(true);
  const lh = Math.round(fontSize * lineHeight * 10) / 10;
  const maxHeight = expanded ? "none" : `${lines}lh`;

  return (
    <div className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-range { accent-color: var(--tau-accent); }
          /* 每 1lh 画一条底线，行线间距就是 lh 的实际大小 */
          .cb-ruled {
            background-image: linear-gradient(to bottom, transparent calc(1lh - 1px), var(--tau-line-2) calc(1lh - 1px));
            background-size: 100% 1lh;
          }
        }
      `}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(220px,34%)]">
        <div className="flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 bg-surface p-4">
          <div className="flex items-center gap-2">
            <span className="text-tau-body text-ink-1">文章摘要</span>
            <ui.Button variant="ghost" size="sm" className="ml-auto" icon={expanded ? icons.ChevronUp : icons.ChevronDown} onClick={() => setExpanded(value => !value)}>
              {expanded ? "收起" : "展开"}
            </ui.Button>
          </div>
          <div className="relative" style={{ fontSize, lineHeight }}>
            <div className={`overflow-hidden text-ink-2 ${ruled ? "cb-ruled" : ""}`} style={{ maxHeight }}>
              在 CSS 中，lh 单位表示当前元素的 line-height。它很适合按行数控制高度，也能让间距跟着行高同步缩放。
              想让某个区域刚好显示 N 行文本时，写 max-height: Nlh 比用 em 或像素更直观。全局调整字号或行高后，折叠高度会自动跟着变化，不必重新计算。
              无论行高写成数字、百分比还是长度，lh 最终都会解析为一个像素值。拖动下方的字号与行高滑块，虚线标出的折叠位置始终停在第 N 行的底部。
            </div>
            {!expanded && (
              <div className="pointer-events-none absolute inset-x-0 border-t border-dashed border-accent" style={{ top: `${lines}lh` }}>
                <span className="absolute -top-2.5 right-0 rounded-full bg-accent-soft px-1.5 font-tau-mono text-tau-tiny leading-[18px] text-accent-text">
                  {lines}lh
                </span>
              </div>
            )}
          </div>
        </div>
        <div className="flex flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">计算过程</span>
          <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-3 gap-y-1.5 font-tau-mono text-tau-sm">
            <dt className="text-ink-3">font-size</dt>
            <dd className="m-0 text-ink-1">{fontSize}px</dd>
            <dt className="text-ink-3">line-height</dt>
            <dd className="m-0 text-ink-1">{lineHeight}</dd>
            <dt className="text-ink-3">1lh</dt>
            <dd className="m-0 text-ink-1">{lh}px</dd>
            <dt className="text-ink-3">{lines}lh</dt>
            <dd className="m-0 text-accent-text">{Math.round(lh * lines * 10) / 10}px</dd>
          </dl>
          <div className="mt-auto flex items-center gap-2 pt-1">
            <span className="text-tau-sm text-ink-2">行数</span>
            <ui.NumberInput size="sm" value={lines} min={1} max={6} onValueChange={value => setLines(value ?? 1)} />
          </div>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <Slider label="字号" value={fontSize} min={12} max={22} step={1} onChange={setFontSize} format={value => `${value}px`} />
        <Slider label="行高" value={lineHeight} min={1.2} max={2.6} step={0.1} onChange={setLineHeight} format={value => value.toFixed(1)} />
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <Chip>max-height: {maxHeight}</Chip>
        <ui.Switch checked={ruled} onCheckedChange={setRuled} label="显示行线" size="sm" />
      </div>
    </div>
  );
};
